#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <cstdint>

using namespace std;

const double PI = acos(-1.0);
const int MOD = 998244353;

// Global tables for FFT twiddle factors (same size as Java: 1 << 20)
static vector<double> cs(1 << 20), sn(1 << 20), csi(1 << 20), sni(1 << 20);
static bool tablesInitialized = false;

void initTables() {
    if (tablesInitialized) return;
    for (int len = 1; len <= (1 << 20); len <<= 1) {
        int half = len / 2;
        for (int i = half; i < len; i++) {
            double angle = 2 * PI * (i - half) / len;
            cs[i] = cos(angle);
            sn[i] = sin(angle);
            csi[i] = cos(-angle);
            sni[i] = sin(-angle);
        }
    }
    tablesInitialized = true;
}

void fft(vector<double>& a, vector<double>& b, bool inverse) {
    int n = a.size();
    // Compute number of trailing zeros of n
    int shift = 32;
    int tn = n;
    while (tn > 1) { shift--; tn >>= 1; }
    // Bit reversal
    for (int i = 1; i < n; i++) {
        int j = 0;
        int tmp = i << shift;
        for (int k = 0; k < 32; k++) {
            j = (j << 1) | (tmp & 1);
            tmp >>= 1;
        }
        if (i < j) {
            swap(a[i], a[j]);
            swap(b[i], b[j]);
        }
    }
    // Iterative FFT
    for (int len = 2; len <= n; len <<= 1) {
        int half = len >> 1;
        int w = cs.size() / len;
        for (int i = 0; i < n; i += len) {
            for (int j = 0, k = 0; j < half; j++, k += w) {
                double wA = inverse ? csi[half + j] : cs[half + j];
                double wB = inverse ? sni[half + j] : sn[half + j];
                double uA = a[i + j];
                double uB = b[i + j];
                double vA = a[i + j + half] * wA - b[i + j + half] * wB;
                double vB = a[i + j + half] * wB + b[i + j + half] * wA;
                a[i + j] = uA + vA;
                b[i + j] = uB + vB;
                a[i + j + half] = uA - vA;
                b[i + j + half] = uB - vB;
            }
        }
    }
    if (inverse) {
        for (int i = 0; i < n; i++) {
            a[i] /= n;
            b[i] /= n;
        }
    }
}

vector<int> multiplyMod(const vector<int>& a, const vector<int>& b, int mod) {
    initTables();  // Ensure tables are ready
    int need = a.size() + b.size() - 1;
    int n = 2;
    while (n < need) n <<= 1;
    if (need == 1) n = 2;   // Handle edge case

    vector<double> aReal(n, 0), aImag(n, 0);
    for (int i = 0; i < (int)a.size(); i++) {
        int x = (a[i] % mod + mod) % mod;
        aReal[i] = x & ((1 << 15) - 1);
        aImag[i] = x >> 15;
    }
    fft(aReal, aImag, false);

    vector<double> bReal(n, 0), bImag(n, 0);
    for (int i = 0; i < (int)b.size(); i++) {
        int x = (b[i] % mod + mod) % mod;
        bReal[i] = x & ((1 << 15) - 1);
        bImag[i] = x >> 15;
    }
    fft(bReal, bImag, false);

    vector<double> faReal(n), faImag(n), fbReal(n), fbImag(n);
    for (int i = 0; i < n; i++) {
        int j = (n - i) & (n - 1);   // same as Java index trick
        double a1r = (aReal[i] + aReal[j]) / 2;
        double a1i = (aImaginary[i] - aImaginary[j]) / 2;
        double a2r = (aImaginary[i] + aImaginary[j]) / 2;
        double a2i = (aReal[j] - aReal[i]) / 2;
        double b1r = (bReal[i] + bReal[j]) / 2;
        double b1i = (bImaginary[i] - bImaginary[j]) / 2;
        double b2r = (bImaginary[i] + bImaginary[j]) / 2;
        double b2i = (bReal[j] - bReal[i]) / 2;
        faReal[i] = a1r * b1r - a1i * b1i - a2r * b2i - a2i * b2r;
        faImag[i] = a1r * b1i + a1i * b1r + a2r * b2r - a2i * b2i;
        fbReal[i] = a1r * b2r - a1i * b2i + a2r * b1r - a2i * b1i;
        fbImag[i] = a1r * b2i + a1i * b2r + a2r * b1i + a2i * b1r;
    }

    fft(faReal, faImag, true);
    fft(fbReal, fbImag, true);

    vector<int> res(need);
    for (int i = 0; i < need; i++) {
        long long aa = (long long)(faReal[i] + 0.5);
        long long bb = (long long)(fbReal[i] + 0.5);
        long long cc = (long long)(faImag[i] + 0.5);
        res[i] = (int)((aa + ((bb % mod) << 15) + ((cc % mod) << 30)) % mod);
    }
    return res;
}

void solve() {
    int n, k;
    cin >> n >> k;
    vector<int> v(10, 0);
    for (int i = 0; i < k; i++) {
        int x;
        cin >> x;
        v[x] = 1;
    }
    vector<int> ans = {1};
    int p = n / 2;
    while (true) {
        if (p % 2 != 0) {
            ans = multiplyMod(ans, v, MOD);
        }
        p /= 2;
        if (p == 0) break;
        v = multiplyMod(v, v, MOD);
    }
    long long res = 0;
    for (int x : ans) {
        res = (res + (long long)x * x) % MOD;
    }
    cout << (int)res << endl;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    solve();
    return 0;
}
